dashboard.definition:
{
        "title": "Moviri TI Manager - Overview & IP Lookup",
        "description": "Operational health monitoring, external feed status, and high-scale IP/CIDR search across F5 (3M+ subnets), Palo Alto, and Manual KV Store collections.",
        "defaults": {
                "dataSources": {
                        "ds.search": {
                                "options": {
                                        "queryParameters": {
                                                "earliest": "$global_time.earliest$",
                                                "latest": "$global_time.latest$"
                                        }
                                }
                        }
                }
        },
        "inputs": {
                "input_time_range": {
                        "type": "input.timerange",
                        "title": "Monitoring Time Range",
                        "options": {
                                "defaultValue": "-24h@h,now",
                                "token": "global_time"
                        }
                },
                "input_deny_ip_search": {
                        "type": "input.text",
                        "title": "Search IP or CIDR (leave empty for 500-row sample; enter IP/CIDR for indexed lookup)",
                        "options": {
                                "defaultValue": "",
                                "token": "deny_ip_query"
                        }
                },
                "input_deny_target_filter": {
                        "type": "input.dropdown",
                        "title": "Target Firewall / Scope",
                        "options": {
                                "items": [
                                        {
                                                "label": "All Targets (F5 + Palo Alto + Manual)",
                                                "value": "all"
                                        },
                                        {
                                                "label": "F5 Enforced Only (denylist_f5)",
                                                "value": "f5"
                                        },
                                        {
                                                "label": "Palo Alto Enforced Only (denylist_paloalto)",
                                                "value": "paloalto"
                                        },
                                        {
                                                "label": "Manual Denylist Only (manual_denylist)",
                                                "value": "manual"
                                        }
                                ],
                                "defaultValue": "all",
                                "token": "deny_target_filter"
                        }
                },
                "input_allow_ip_search": {
                        "type": "input.text",
                        "title": "Search Whitelisted IP or CIDR (exact or subnet match)",
                        "options": {
                                "defaultValue": "",
                                "token": "allow_ip_query"
                        }
                }
        },
        "dataSources": {
                "ds_kpi_f5_count": {
                        "type": "ds.search",
                        "name": "KPI F5 Denylist Count",
                        "options": {
                                "query": "| inputlookup denylist_f5 | stats count"
                        }
                },
                "ds_kpi_pa_count": {
                        "type": "ds.search",
                        "name": "KPI Palo Alto Denylist Count",
                        "options": {
                                "query": "| inputlookup denylist_paloalto | stats count"
                        }
                },
                "ds_kpi_allow_count": {
                        "type": "ds.search",
                        "name": "KPI Enforced Allowlist Count",
                        "options": {
                                "query": "| inputlookup allowlist | stats count"
                        }
                },
                "ds_kpi_manual_counts": {
                        "type": "ds.search",
                        "name": "KPI Manual Entries Count",
                        "options": {
                                "query": "| inputlookup manual_denylist | stats count as manual_deny | appendcols [| inputlookup manual_allowlist | stats count as manual_allow] | eval summary=manual_deny.\" Deny / \".manual_allow.\" Allow\" | fields summary"
                        }
                },
                "ds_kpi_errors": {
                        "type": "ds.search",
                        "name": "KPI Errors Count",
                        "options": {
                                "query": "index=_internal \"[TI MANAGER ERROR]\" | stats count"
                        }
                },
                "ds_kpi_warnings": {
                        "type": "ds.search",
                        "name": "KPI Warnings Count",
                        "options": {
                                "query": "index=_internal \"[TI MANAGER WARNING]\" | stats count"
                        }
                },
                "ds_chart_audit_activity": {
                        "type": "ds.search",
                        "name": "Audit Events Over Time",
                        "options": {
                                "query": "index=* sourcetype IN (\"ti_manager:diff:f5\", \"ti_manager:diff:paloalto\") | eval series=list_name.\" - \".action | timechart count by series"
                        }
                },
                "ds_chart_sync_duration": {
                        "type": "ds.search",
                        "name": "Sync Cycle Duration Over Time",
                        "options": {
                                "query": "index=_internal \"[TI MANAGER INFO]\" \"[SYNC] Cycle completed successfully\" | rex field=_raw \"target=(?<target>\\w+).*?total_elapsed=(?<elapsed>[\\d\\.]+)s\" | timechart max(elapsed) as \"Max Duration (s)\" by target"
                        }
                },
                "ds_table_feeds_status": {
                        "type": "ds.search",
                        "name": "External Threat Feeds Health",
                        "options": {
                                "query": "index=_internal (\"[TI MANAGER INFO] [FEED]\" OR \"[TI MANAGER ERROR] [FEED]\") | rex field=_raw \"\\[(?<severity>INFO|ERROR)\\] \\[FEED\\] (?<msg>.*?)\\s+url=(?<url>\\S+)\" | rex field=_raw \"unique_ips=(?<unique_ips>\\d+)\" | rex field=_raw \"regex_fails=(?<regex_fails>\\d+)\\s+invalid_ips=(?<invalid_ips>\\d+)\" | rex field=_raw \"elapsed=(?<elapsed>[\\d\\.]+)s\" | eval status=case(severity==\"ERROR\", \"ERROR\", like(msg, \"%304%\"), \"OK (304 Cached)\", 1==1, \"OK (Updated)\") | stats latest(_time) as last_run, latest(status) as Status, latest(unique_ips) as \"Unique CIDRs\", latest(regex_fails) as \"Regex Skips\", latest(invalid_ips) as \"Invalid IPs\", latest(elapsed) as \"Duration (s)\" by url | eval \"Last Check\"=strftime(last_run, \"%Y-%m-%d %H:%M:%S\") | table \"Last Check\", Status, url, \"Unique CIDRs\", \"Regex Skips\", \"Invalid IPs\", \"Duration (s)\" | sort Status, url"
                        }
                },
                "ds_table_recent_errors": {
                        "type": "ds.search",
                        "name": "Recent Errors and Warnings",
                        "options": {
                                "query": "index=_internal (\"[TI MANAGER ERROR]\" OR \"[TI MANAGER WARNING]\") | rex field=_raw \"file=(?<source_file>[^:\\s]+:\\w+:\\d+)\\s+\\|\\s+\\[TI MANAGER (?<level>ERROR|WARNING)\\]\\s+(?<message>.*)\" | eval Time=strftime(_time, \"%Y-%m-%d %H:%M:%S\") | table Time, level, source_file, message | sort - Time | head 100"
                        }
                },
                "ds_deny_enforced_base": {
                        "type": "ds.search",
                        "name": "Enforced Denylists Search (Index-Pushdown)",
                        "options": {
                                "query": "| inputlookup denylist_f5 [| makeresults | eval q=trim(\"$deny_ip_query$\") | eval search=case(q==\"\", \"max=500\", match(q, \"^(\\d{1,3})\\.\") AND NOT match(q, \"/[0-7]$\"), \"where ip=\\\"\".replace(q, \"^(\\d{1,3})\\..*\", \"\\1.*\") .\"\\\"\", match(q, \"/[0-7]$\"), \"\", 1==1, \"where ip=\\\"*\".q.\"*\") | return $search] | eval target=\"F5\" | append [| inputlookup denylist_paloalto [| makeresults | eval q=trim(\"$deny_ip_query$\") | eval search=case(q==\"\", \"max=500\", match(q, \"^(\\d{1,3})\\.\") AND NOT match(q, \"/[0-7]$\"), \"where ip=\\\"\".replace(q, \"^(\\d{1,3})\\..*\", \"\\1.*\") .\"\\\"\", match(q, \"/[0-7]$\"), \"\", 1==1, \"where ip=\\\"*\".q.\"*\") | return $search] | eval target=\"Palo Alto\"] | eval q=trim(\"$deny_ip_query$\"), scope=\"$deny_target_filter$\" | where (scope==\"all\" OR (scope==\"f5\" AND target==\"F5\") OR (scope==\"paloalto\" AND target==\"Palo Alto\")) | where (q==\"\" OR like(ip, \"%\".q.\"%\") OR coalesce(cidrmatch(ip, q), false()) OR coalesce(cidrmatch(q, ip), false())) | stats values(target) as targets by ip | eval \"F5 Status\"=if(mvfind(targets, \"F5\")>=0, \"BLOCKED\", \"-\"), \"Palo Alto Status\"=if(mvfind(targets, \"Palo Alto\")>=0, \"BLOCKED\", \"-\") | rename ip as \"Enforced Subnet (CIDR)\" | table \"Enforced Subnet (CIDR)\", \"F5 Status\", \"Palo Alto Status\""
                        }
                },
                "ds_deny_enforced_kpi": {
                        "type": "ds.chain",
                        "name": "Enforced Denylists KPI",
                        "options": {
                                "extend": "ds_deny_enforced_base",
                                "query": "| stats count(eval('F5 Status'==\"BLOCKED\")) as f5_matches, count(eval('Palo Alto Status'==\"BLOCKED\")) as pa_matches | eval q=trim(\"$deny_ip_query$\"), summary=if(q==\"\", \"Sample: \".f5_matches.\" F5 / \".pa_matches.\" PA (Enter IP to search all 3M)\", f5_matches.\" F5 / \".pa_matches.\" Palo Alto\") | fields summary"
                        }
                },
                "ds_deny_enforced_table": {
                        "type": "ds.chain",
                        "name": "Enforced Denylists Table",
                        "options": {
                                "extend": "ds_deny_enforced_base",
                                "query": "| sort \"Enforced Subnet (CIDR)\" | head 1000"
                        }
                },
                "ds_deny_manual_base": {
                        "type": "ds.search",
                        "name": "Manual Denylist Search",
                        "options": {
                                "query": "| inputlookup manual_denylist | eval q=trim(\"$deny_ip_query$\"), scope=\"$deny_target_filter$\" | where (scope!=\"paloalto\" OR target==\"Both (F5+PaloAlto)\") | where (q==\"\" OR like(ip, \"%\".q.\"%\") OR like(lower(coalesce(reason, \"\")), \"%\".lower(q).\"%\") OR like(lower(coalesce(user, \"\")), \"%\".lower(q).\"%\") OR like(lower(coalesce(source, \"\")), \"%\".lower(q).\"%\") OR coalesce(cidrmatch(ip, q), false()) OR coalesce(cidrmatch(q, ip), false())) | eval exp_epoch=strptime(expirydate, \"%Y-%m-%dT%H:%M:%S.%3NZ\"), Status=case(isnull(expirydate) OR expirydate==\"\", \"Active (Permanent)\", exp_epoch > now(), \"Active (Timed)\", 1==1, \"Expired (Still in KV Store)\"), Source=coalesce(source, \"Manual Entry\"), Expiry=if(isnull(expirydate) OR expirydate==\"\", \"Never\", expirydate) | table ip, target, Status, user, reason, Source, timestamp, Expiry | sort - timestamp"
                        }
                },
                "ds_deny_manual_kpi": {
                        "type": "ds.chain",
                        "name": "Manual Denylist KPI",
                        "options": {
                                "extend": "ds_deny_manual_base",
                                "query": "| stats count"
                        }
                },
                "ds_deny_manual_table": {
                        "type": "ds.chain",
                        "name": "Manual Denylist Table",
                        "options": {
                                "extend": "ds_deny_manual_base",
                                "query": "| rename ip as \"IP / CIDR\", target as \"Target\", user as \"Submitted By\", reason as \"Reason\", timestamp as \"Added On\", Expiry as \"Expiry Date\" | head 1000"
                        }
                },
                "ds_allow_enforced_base": {
                        "type": "ds.search",
                        "name": "Enforced Allowlist Search",
                        "options": {
                                "query": "| inputlookup allowlist | eval q=trim(\"$allow_ip_query$\") | where (q==\"\" OR like(ip, \"%\".q.\"%\") OR coalesce(cidrmatch(ip, q), false()) OR coalesce(cidrmatch(q, ip), false())) | eval Classification=if(cidrmatch(\"10.0.0.0/8\", ip) OR cidrmatch(\"172.16.0.0/12\", ip) OR cidrmatch(\"192.168.0.0/16\", ip) OR cidrmatch(\"127.0.0.0/8\", ip) OR cidrmatch(\"169.254.0.0/16\", ip) OR cidrmatch(\"100.64.0.0/10\", ip), \"Protected Private Range (Static)\", \"Manual Exception / Whitelist Feed\") | rename ip as \"Allowed Subnet (CIDR)\" | table \"Allowed Subnet (CIDR)\", Classification"
                        }
                },
                "ds_allow_enforced_kpi": {
                        "type": "ds.chain",
                        "name": "Enforced Allowlist KPI",
                        "options": {
                                "extend": "ds_allow_enforced_base",
                                "query": "| stats count"
                        }
                },
                "ds_allow_enforced_table": {
                        "type": "ds.chain",
                        "name": "Enforced Allowlist Table",
                        "options": {
                                "extend": "ds_allow_enforced_base",
                                "query": "| sort \"Allowed Subnet (CIDR)\" | head 1000"
                        }
                },
                "ds_allow_manual_base": {
                        "type": "ds.search",
                        "name": "Manual Allowlist Search",
                        "options": {
                                "query": "| inputlookup manual_allowlist | eval q=trim(\"$allow_ip_query$\") | where (q==\"\" OR like(ip, \"%\".q.\"%\") OR like(lower(coalesce(reason, \"\")), \"%\".lower(q).\"%\") OR like(lower(coalesce(user, \"\")), \"%\".lower(q).\"%\") OR like(lower(coalesce(source, \"\")), \"%\".lower(q).\"%\") OR coalesce(cidrmatch(ip, q), false()) OR coalesce(cidrmatch(q, ip), false())) | eval exp_epoch=strptime(expirydate, \"%Y-%m-%dT%H:%M:%S.%3NZ\"), Status=case(isnull(expirydate) OR expirydate==\"\", \"Active (Permanent)\", exp_epoch > now(), \"Active (Timed)\", 1==1, \"Expired (Still in KV Store)\"), Source=coalesce(source, \"Manual Entry\"), Expiry=if(isnull(expirydate) OR expirydate==\"\", \"Never\", expirydate) | table ip, Status, user, reason, Source, timestamp, Expiry | sort - timestamp"
                        }
                },
                "ds_allow_manual_kpi": {
                        "type": "ds.chain",
                        "name": "Manual Allowlist KPI",
                        "options": {
                                "extend": "ds_allow_manual_base",
                                "query": "| stats count"
                        }
                },
                "ds_allow_manual_table": {
                        "type": "ds.chain",
                        "name": "Manual Allowlist Table",
                        "options": {
                                "extend": "ds_allow_manual_base",
                                "query": "| rename ip as \"IP / CIDR\", user as \"Submitted By\", reason as \"Reason\", timestamp as \"Allowed On\", Expiry as \"Expiry Date\" | head 1000"
                        }
                }
        },
        "visualizations": {
                "viz_kpi_f5": {
                        "type": "splunk.singlevalue",
                        "title": "F5 Blocked Subnets",
                        "dataSources": {
                                "primary": "ds_kpi_f5_count"
                        },
                        "options": {
                                "majorColor": "#dc4e41",
                                "sparklineDisplay": "off"
                        }
                },
                "viz_kpi_pa": {
                        "type": "splunk.singlevalue",
                        "title": "Palo Alto Blocked Subnets",
                        "dataSources": {
                                "primary": "ds_kpi_pa_count"
                        },
                        "options": {
                                "majorColor": "#f1813f",
                                "sparklineDisplay": "off"
                        }
                },
                "viz_kpi_allow": {
                        "type": "splunk.singlevalue",
                        "title": "Enforced Allowlist Subnets",
                        "dataSources": {
                                "primary": "ds_kpi_allow_count"
                        },
                        "options": {
                                "majorColor": "#53a051",
                                "sparklineDisplay": "off"
                        }
                },
                "viz_kpi_manual": {
                        "type": "splunk.singlevalue",
                        "title": "Manual KV Store Records",
                        "dataSources": {
                                "primary": "ds_kpi_manual_counts"
                        },
                        "options": {
                                "majorColor": "#006d9c",
                                "sparklineDisplay": "off"
                        }
                },
                "viz_kpi_errors": {
                        "type": "splunk.singlevalue",
                        "title": "TI Manager Errors",
                        "dataSources": {
                                "primary": "ds_kpi_errors"
                        },
                        "options": {
                                "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
                                "majorColorEditorConfig": [
                                        {
                                                "to": 1,
                                                "value": "#53a051"
                                        },
                                        {
                                                "from": 1,
                                                "value": "#dc4e41"
                                        }
                                ],
                                "sparklineDisplay": "off"
                        }
                },
                "viz_kpi_warnings": {
                        "type": "splunk.singlevalue",
                        "title": "TI Manager Warnings",
                        "dataSources": {
                                "primary": "ds_kpi_warnings"
                        },
                        "options": {
                                "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
                                "majorColorEditorConfig": [
                                        {
                                                "to": 1,
                                                "value": "#53a051"
                                        },
                                        {
                                                "from": 1,
                                                "value": "#f8be34"
                                        }
                                ],
                                "sparklineDisplay": "off"
                        }
                },
                "viz_chart_audit": {
                        "type": "splunk.column",
                        "title": "Firewall List Changes Over Time (Added vs Removed)",
                        "dataSources": {
                                "primary": "ds_chart_audit_activity"
                        },
                        "options": {
                                "stackMode": "stacked",
                                "legendDisplay": "bottom"
                        }
                },
                "viz_chart_sync": {
                        "type": "splunk.line",
                        "title": "Merge Sync Cycle Duration by Target (Seconds)",
                        "dataSources": {
                                "primary": "ds_chart_sync_duration"
                        },
                        "options": {
                                "legendDisplay": "bottom",
                                "nullValueDisplay": "connect"
                        }
                },
                "viz_table_feeds": {
                        "type": "splunk.table",
                        "title": "External Threat Intelligence Feeds Health Status (get_ti)",
                        "dataSources": {
                                "primary": "ds_table_feeds_status"
                        },
                        "options": {
                                "count": 20,
                                "showRowNumbers": false,
                                "columnFormat": {
                                        "Status": {
                                                "data": "> table | seriesByName(\"Status\") | formatByType(StatusColumnFormatEditorConfig)",
                                                "align": "auto",
                                                "headerAlign": "auto",
                                                "textOverflow": "break-word",
                                                "rowColors": "> table | seriesByName(\"Status\") | matchValue(StatusRowColorsEditorConfig)"
                                        },
                                        "Unique CIDRs": {
                                                "data": "> table | seriesByName(\"Unique CIDRs\") | formatByType(Unique_CIDRsColumnFormatEditorConfig)",
                                                "align": "auto",
                                                "headerAlign": "auto",
                                                "textOverflow": "break-word",
                                                "rowColors": "> table | seriesByName(\"Unique CIDRs\") | rangeValue(Unique_CIDRsRowColorsEditorConfig)"
                                        },
                                        "Invalid IPs": {
                                                "data": "> table | seriesByName(\"Invalid IPs\") | formatByType(Invalid_IPsColumnFormatEditorConfig)",
                                                "align": "auto",
                                                "headerAlign": "auto",
                                                "textOverflow": "break-word",
                                                "rowColors": "> table | seriesByName(\"Invalid IPs\") | rangeValue(Invalid_IPsRowColorsEditorConfig)"
                                        }
                                }
                        },
                        "context": {
                                "StatusColumnFormatEditorConfig": {
                                        "string": {
                                                "unitPosition": "after"
                                        }
                                },
                                "StatusRowColorsEditorConfig": [
                                        {
                                                "match": "OK (Updated)",
                                                "value": "#118832"
                                        },
                                        {
                                                "match": "OK (304 Cached)",
                                                "value": "#CBA700"
                                        },
                                        {
                                                "match": "ERROR",
                                                "value": "#d41f1f"
                                        }
                                ],
                                "Unique_CIDRsColumnFormatEditorConfig": {
                                        "number": {
                                                "thousandSeparated": false,
                                                "unitPosition": "after"
                                        }
                                },
                                "Unique_CIDRsRowColorsEditorConfig": [
                                        {
                                                "value": "#118832",
                                                "to": 10000
                                        },
                                        {
                                                "value": "#669922",
                                                "from": 10000,
                                                "to": 100000
                                        },
                                        {
                                                "value": "#CBA700",
                                                "from": 100000,
                                                "to": 1000000
                                        },
                                        {
                                                "value": "#D94E17",
                                                "from": 1000000,
                                                "to": 2000000
                                        },
                                        {
                                                "value": "#D41F1F",
                                                "from": 2000000
                                        }
                                ],
                                "Invalid_IPsColumnFormatEditorConfig": {
                                        "number": {
                                                "thousandSeparated": false,
                                                "unitPosition": "after"
                                        }
                                },
                                "Invalid_IPsRowColorsEditorConfig": [
                                        {
                                                "value": "#118832",
                                                "to": 1
                                        },
                                        {
                                                "value": "#D41F1F",
                                                "from": 1
                                        }
                                ]
                        }
                },
                "viz_table_errors": {
                        "type": "splunk.table",
                        "title": "Recent Add-on Errors & Warnings",
                        "dataSources": {
                                "primary": "ds_table_recent_errors"
                        },
                        "options": {
                                "count": 15,
                                "showRowNumbers": false
                        }
                },
                "viz_deny_kpi_enforced": {
                        "type": "splunk.singlevalue",
                        "title": "Matching Enforced Subnets (F5 / Palo Alto)",
                        "dataSources": {
                                "primary": "ds_deny_enforced_kpi"
                        },
                        "options": {
                                "majorColor": "#dc4e41",
                                "sparklineDisplay": "off"
                        }
                },
                "viz_deny_kpi_manual": {
                        "type": "splunk.singlevalue",
                        "title": "Matching Manual Denylist Entries",
                        "dataSources": {
                                "primary": "ds_deny_manual_kpi"
                        },
                        "options": {
                                "majorColor": "#f1813f",
                                "sparklineDisplay": "off"
                        }
                },
                "viz_deny_table_enforced": {
                        "type": "splunk.table",
                        "title": "Active Enforced Firewall Denylists (denylist_f5 & denylist_paloalto — max 1,000 rows)",
                        "dataSources": {
                                "primary": "ds_deny_enforced_table"
                        },
                        "options": {
                                "count": 20,
                                "showRowNumbers": false
                        }
                },
                "viz_deny_table_manual": {
                        "type": "splunk.table",
                        "title": "Manual Denylist Metadata & Audit Details (manual_denylist — max 1,000 rows)",
                        "dataSources": {
                                "primary": "ds_deny_manual_table"
                        },
                        "options": {
                                "count": 20,
                                "showRowNumbers": false
                        }
                },
                "viz_allow_kpi_enforced": {
                        "type": "splunk.singlevalue",
                        "title": "Matching Enforced Allowlist Subnets",
                        "dataSources": {
                                "primary": "ds_allow_enforced_kpi"
                        },
                        "options": {
                                "majorColor": "#53a051",
                                "sparklineDisplay": "off"
                        }
                },
                "viz_allow_kpi_manual": {
                        "type": "splunk.singlevalue",
                        "title": "Matching Manual Allowlist Entries",
                        "dataSources": {
                                "primary": "ds_allow_manual_kpi"
                        },
                        "options": {
                                "majorColor": "#006d9c",
                                "sparklineDisplay": "off"
                        }
                },
                "viz_allow_table_enforced": {
                        "type": "splunk.table",
                        "title": "Active Enforced Allowlist (allowlist — Feeds, Manual & Private Networks — max 1,000 rows)",
                        "dataSources": {
                                "primary": "ds_allow_enforced_table"
                        },
                        "options": {
                                "count": 20,
                                "showRowNumbers": false
                        }
                },
                "viz_allow_table_manual": {
                        "type": "splunk.table",
                        "title": "Manual Allowlist Metadata & Exceptions (manual_allowlist — max 1,000 rows)",
                        "dataSources": {
                                "primary": "ds_allow_manual_table"
                        },
                        "options": {
                                "count": 20,
                                "showRowNumbers": false
                        }
                }
        },
        "layout": {
                "options": {},
                "globalInputs": [
                        "input_time_range"
                ],
                "tabs": {
                        "items": [
                                {
                                        "layoutId": "tab_overview",
                                        "label": "Overview & System Health"
                                },
                                {
                                        "layoutId": "tab_denylist",
                                        "label": "Denylist IP Search"
                                },
                                {
                                        "layoutId": "tab_allowlist",
                                        "label": "Allowlist IP Search"
                                }
                        ]
                },
                "layoutDefinitions": {
                        "tab_overview": {
                                "type": "grid",
                                "options": {
                                        "width": 1440,
                                        "height": 1120
                                },
                                "structure": [
                                        {
                                                "item": "viz_kpi_f5",
                                                "type": "block",
                                                "position": {
                                                        "x": 0,
                                                        "y": 0,
                                                        "w": 240,
                                                        "h": 130
                                                }
                                        },
                                        {
                                                "item": "viz_kpi_pa",
                                                "type": "block",
                                                "position": {
                                                        "x": 240,
                                                        "y": 0,
